import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let {n} and {ell} be integers with {n} >= {ell} >= 2. Real numbers a_1, a_2, ..., a_{n} satisfy the two constraints: (i) the sum of absolute values equals {s_value}, that is, sum_{k=1}^n |a_k| = {s_value}; and (ii) the weighted sum of absolute values equals {t_value}, that is, sum_{k=1}^n k*|a_k| = {t_value}. Determine the minimum possible value of sum_{k=1}^n a_k^2.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose ell between 2 and 6
ell = rng.randint(2, 6)
# Choose n at least ell+1 to activate the tail where coefficients become nonpositive
n = rng.randint(ell + 1, ell + 20)
# Precompute triangular sums for control (not strictly needed here but useful for scaling)
sum_lin = ell * (ell + 1) // 2  # sum_{j=1}^ell j
# Choose S as a positive multiple of sum_lin to make the extremal pattern integral (optional)
mult1 = rng.randint(3, 9)
mult2 = rng.randint(1, 5)
s_value = float(sum_lin * mult1 * mult2)
# With the constructed family, the optimality condition is enforced by setting
# T = S * (ell + 2) / 3
t_value = s_value * (ell + 2) / 3.0
return {
    'n': int(n),
    'ell': int(ell),
    's_value': float(s_value),
    't_value': float(t_value)
}

    def verifier(assign):
# Validate inputs and compute the minimum
try:
    n = int(assign.get('n', None))
    ell = int(assign.get('ell', None))
    s_value = float(assign.get('s_value', None))
    t_value = float(assign.get('t_value', None))
except Exception:
    # Missing or invalid types
    return (False, None)
# Basic domain checks
if not (ell >= 2 and n >= ell):
    # n must be at least ell, ell at least 2
    return (False, None)
if not (s_value > 0):
    return (False, None)
# Check the constructed consistency condition: T must equal S * (ell + 2) / 3
if abs(t_value - s_value * (ell + 2) / 3.0) > 1e-9:
    return (False, None)
# The proven minimum is S^2 * 2*(2*ell + 1) / (3*ell*(ell + 1))
min_value = (s_value ** 2) * (2.0 * (2 * ell + 1)) / (3.0 * ell * (ell + 1))
return (True, min_value)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

